import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Container, Row, Col, Card, Form, Button, Alert } from 'react-bootstrap';

const ShopPage = () => {
  const navigate = useNavigate();
  const [quantities, setQuantities] = useState({});
  const [cart, setCart] = useState([]);
  const [showAlert, setShowAlert] = useState(false);
  const [alertMessage, setAlertMessage] = useState('');

  // Tilapia products only
  const tilapiaProducts = [
    { id: 1, name: "Fresh Tilapia", price: 12.99, unit: "kg", description: "Freshly caught from Lake Victoria" },
    { id: 2, name: "Premium Tilapia Fillets", price: 18.99, unit: "kg", description: "Boneless, skinless fillets" },
    { id: 3, name: "Smoked Tilapia", price: 15.99, unit: "kg", description: "Traditional smoked flavor" },
    { id: 4, name: "Tilapia Steaks", price: 14.99, unit: "kg", description: "Ready-to-grill portions" },
    { id: 5, name: "Whole Frozen Tilapia", price: 10.99, unit: "kg", description: "Flash frozen for freshness" },
    { id: 6, name: "Value Pack Tilapia", price: 9.99, unit: "kg", description: "5kg minimum purchase" },
  ];

  const handleQuantityChange = (id, value) => {
    setQuantities({
      ...quantities,
      [id]: value
    });
  };

  const handleAddToCart = (product) => {
    const quantity = parseFloat(quantities[product.id]);
    if (!quantity || quantity <= 0) {
      setAlertMessage(`Please enter a valid quantity for ${product.name}`);
      setShowAlert(true);
      setTimeout(() => setShowAlert(false), 3000);
      return;
    }

    const newItem = {
      ...product,
      quantity,
      total: (product.price * quantity).toFixed(2)
    };

    setCart([...cart, newItem]);
    setAlertMessage(`Added ${quantity}kg of ${product.name} to cart!`);
    setShowAlert(true);
    setQuantities({ ...quantities, [product.id]: '' });

    setTimeout(() => setShowAlert(false), 3000);
  };

  const calculateTotal = () => {
    return cart.reduce((sum, item) => sum + parseFloat(item.total), 0).toFixed(2);
  };

  return (
    <Container className="py-5">
      {/* Success Alert */}
      <div style={{ position: 'fixed', top: '20px', right: '20px', zIndex: 1050 }}>
        <Alert show={showAlert} variant="success" className="shadow-sm" style={{ minWidth: '250px' }}>
          {alertMessage}
        </Alert>
      </div>

      <Row>
        <Col lg={10} className="mx-auto">
          {/* Header Section */}
          <h1 className="display-4 text-center mb-4 fw-bold">🐟 Fresh Tilapia</h1>
          <p className="lead text-center mb-5 text-muted">
            Premium tilapia harvested daily by our women-led fishing communities.
          </p>

          {/* Products Grid */}
          <Row className="g-4">
            {tilapiaProducts.map((product) => (
              <Col key={product.id} md={6} lg={4}>
                <Card className="h-100 border-0 shadow-sm rounded-4 overflow-hidden hover-lift">
                  <div 
                    className="bg-primary bg-opacity-10 d-flex align-items-center justify-content-center py-4"
                    style={{ minHeight: '180px' }}
                  >
                    <i className="bi bi-fish display-3 text-primary"></i>
                  </div>
                  <Card.Body className="d-flex flex-column p-4">
                    <h5 className="text-primary mb-2">{product.name}</h5>
                    <p className="text-muted small mb-3">{product.description}</p>
                    <p className="fw-bold fs-5 text-success mb-4">${product.price.toFixed(2)} / kg</p>
                    
                    <Form.Group className="mb-3">
                      <Form.Label>Quantity (kg)</Form.Label>
                      <Form.Control 
                        type="number" 
                        min="0.1"
                        step="0.1"
                        value={quantities[product.id] || ''}
                        onChange={(e) => handleQuantityChange(product.id, e.target.value)}
                        placeholder="Enter kg"
                        className="form-control-lg"
                      />
                    </Form.Group>
                    
                    <Button 
                      variant="primary" 
                      className="w-100 py-2 mt-auto"
                      onClick={() => handleAddToCart(product)}
                    >
                      Add to Cart
                    </Button>
                  </Card.Body>
                </Card>
              </Col>
            ))}
          </Row>

          {/* Cart Summary */}
          {cart.length > 0 && (
            <div className="mt-5 p-4 border rounded-4 bg-white shadow-sm">
              <h4 className="mb-3">🛒 Your Cart</h4>
              <ul className="list-group list-group-flush mb-3">
                {cart.map((item, index) => (
                  <li key={index} className="list-group-item px-0 py-3 border-bottom">
                    <div className="d-flex justify-content-between align-items-center">
                      <div>
                        <strong>{item.name}</strong> ({item.quantity}kg)
                      </div>
                      <span className="text-primary fw-bold">${item.total}</span>
                    </div>
                  </li>
                ))}
              </ul>
              <div className="d-flex justify-content-between align-items-center">
                <strong>Total:</strong>
                <strong className="text-success fs-5">${calculateTotal()}</strong>
              </div>
              <div className="mt-3 d-grid gap-2 d-md-block">
                <Button variant="success" size="lg" onClick={() => navigate('/checkout')}>
                  Proceed to Checkout
                </Button>
                <Button variant="outline-secondary" onClick={() => setCart([])}>
                  Clear Cart
                </Button>
              </div>
            </div>
          )}

          {/* Call to Action */}
          <div className="mt-5 p-4 bg-light rounded-4 text-center">
            <h3 className="mb-3">Community Supported Fisheries</h3>
            <p className="mb-4">
              Every kilogram purchased directly supports our women fishers and their families. 
              Subscribe for weekly fresh tilapia deliveries at special discounted prices!
            </p>
            
            <div className="d-flex flex-wrap justify-content-center gap-3">
              <Button 
                variant="success"
                size="lg"
                onClick={() => navigate('/join')}
                className="px-4"
              >
                Subscribe Now
              </Button>
              <Button 
                variant="outline-primary"
                size="lg"
                onClick={() => navigate('/about')}
                className="px-4"
              >
                Learn About Our Community
              </Button>
            </div>
          </div>
        </Col>
      </Row>
    </Container>
  );
};

export default ShopPage;
